insert into properties (id, building_id, reference_number, slug, title, teaser, description, category, categories, property_type, status, price_type, price_note, commission_free, commission_months, commission_note, features, area_range_min_sqm, area_range_max_sqm, expose_pdf_url, featured_rank, source, external_id) values (md5('property-22077')::uuid, md5('building-am-sandtorkai-38-41-20457')::uuid, '22077', 'aussergewoehnliche-bueroflaeche-in-der-hafencity-22077', 'Außergewöhnliche Bürofläche in der HafenCity', 'Das Columbus Haus bildet das Tor zur HafenCity. Der markante Turm besticht durch seine beeindruckende Glaskonstruktion und die außergewöhnliche Architektur. Die Hamburger City ist …', 'Das Columbus Haus bildet das Tor zur HafenCity. Der markante Turm besticht durch seine beeindruckende Glaskonstruktion und die außergewöhnliche Architektur. Die Hamburger City ist in wenigen Gehminuten erreicht. Die Anbindung an den ÖPNV ist durch die U-Bahn Stationen Baumwall und Rödingsmarkt gesichert. Im Umfeld befinden sich zahlreiche Cafés und Restaurants. Die angebotene Mietfläche befindet sich im 2.OG und verfügt aktuell über einen Teppichbodenbelag, ein Beleuchtungskonzept, teilweise Glastrennwände, eine großzügige Pantry, eine kleine Terrasse sowie getrennte Sanitäreinheiten. Die weitere Aufteilung und Ausstattung erfolgt in Absprache mit dem zukünftigen Mieter. Pkw-Stellplätze stehen zur Anmietung bereit.', 'buero-praxis', array['buero-praxis']::property_category[], 'buero', 'published', 'qm', 'zzgl. NK u. MwSt.', true, null, 'Dieses Mietangebot ist courtagefrei für den Mieter bei Abschluss eines Mietvertrages mit einer festen Mietlaufzeit von mindestens 5 Jahren.', array['stellplaetze', 'wasserblick']::text[], 142, 1156, 'https://www.buerohamburg.de/objects/pdf/BHI_22077.pdf', null, 'filemaker', '22077') on conflict (id) do nothing;
