insert into properties (id, building_id, reference_number, slug, title, teaser, description, category, categories, property_type, status, price_type, price_note, commission_free, commission_months, commission_note, features, area_range_min_sqm, area_range_max_sqm, expose_pdf_url, featured_rank, source, external_id) values (md5('property-24615')::uuid, md5('building-van-der-smissen-strasse-9-22767')::uuid, '24615', 'dockland-arbeiten-mit-blick-auf-die-elbe-24615', 'Dockland – Arbeiten mit Blick auf die Elbe', 'In unmittelbarer Nähe zur Großen Elbstraße und Neumühlen, direkt an der Elbe, befindet sich das architektonisch außergewöhnliche Dockland. Das markante Gebäude in Form einer …', 'In unmittelbarer Nähe zur Großen Elbstraße und Neumühlen, direkt an der Elbe, befindet sich das architektonisch außergewöhnliche Dockland. Das markante Gebäude in Form einer Luxusyacht beeindruckt mit seiner extravaganten Architektur und einem einmaligen Blick über die Elbe. Hier verbinden sich Tradition und Innovation zu einer inspirierenden Arbeitsatmosphäre, während die vielfältige Gastronomie im direkten Umfeld die Attraktivität dieses unverwechselbaren Standortes zusätzlich unterstreicht.insert into rental_units (id, property_id, label, area_sqm, rent_per_sqm, rent_total_monthly, source, external_id) values (md5('unit-24615-1')::uuid, md5('property-24615')::uuid, 'Mietfläche', 1228, 25, null, 'filemaker', '24615-1') on conflict (id) do nothing;
