insert into properties (id, building_id, reference_number, slug, title, teaser, description, category, categories, property_type, status, price_type, price_note, commission_free, commission_months, commission_note, features, area_range_min_sqm, area_range_max_sqm, expose_pdf_url, featured_rank, source, external_id) values (md5('property-23979')::uuid, md5('building-humboldtstrasse-58-62-22083')::uuid, '23979', 'uhlenhorst-hochwertige-bueroflaeche-im-humboldt-campus-23979', 'Uhlenhorst: Hochwertige Bürofläche im Humboldt-Campus', 'Der von dem namenhaften Architekturbüro Bothe Richter Teherani entworfene Humboldt-Campus befindet sich in ruhiger aber zentraler Lage des angesagten Stadtteils Barmbek Süd. Die …', 'Der von dem namenhaften Architekturbüro Bothe Richter Teherani entworfene Humboldt-Campus befindet sich in ruhiger aber zentraler Lage des angesagten Stadtteils Barmbek Süd. Die nahe gelegene U-Bahnstation Mundsburg sowie diverse Buslinien sorgen für eine gute Anbindung an das öffentliche Verkehrsnetz. Das nur wenige Fußminuten entfernte Einkaufszentrum Hamburger Meile und der Winterhuder Weg sorgen für Zugang zu allen Geschäften des täglichen Bedarfs sowie einer Vielzahl an Cafés und Restaurants.insert into rental_units (id, property_id, label, area_sqm, rent_per_sqm, rent_total_monthly, source, external_id) values (md5('unit-23979-1')::uuid, md5('property-23979')::uuid, 'Mietfläche', 1239, 18.5, null, 'filemaker', '23979-1') on conflict (id) do nothing;
