  (md5('image-25175-2')::uuid, md5('property-25175')::uuid, 'https://www.buerohamburg.de/objects/images/25175/02_webBig.jpg', 'Hammerbrook: Moderne Bürofläche direkt am Fleet – Bild 2', 1, 'filemaker', '25175-02'),
