insert into properties (id, building_id, reference_number, slug, title, teaser, description, category, categories, property_type, status, price_type, price_note, commission_free, commission_months, commission_note, features, area_range_min_sqm, area_range_max_sqm, expose_pdf_url, featured_rank, source, external_id) values (md5('property-24103')::uuid, md5('building-spitalerstrasse-1-20095')::uuid, '24103', 'repraesentatives-buero-und-geschaeftsgebaeude-in-erstklassiger-lage-24103', 'Repräsentatives Büro- und Geschäftsgebäude in erstklassiger Lage', 'In bester Lage direkt gegenüber dem Hamburger Hauptbahnhof, am Eingang der beliebten Spitalerstraße mit ihren vielfältigen Einkaufs-, Gastronomie- und Freizeitangeboten, befindet …', 'In bester Lage direkt gegenüber dem Hamburger Hauptbahnhof, am Eingang der beliebten Spitalerstraße mit ihren vielfältigen Einkaufs-, Gastronomie- und Freizeitangeboten, befindet sich das um 1906 errichtete ehemalige Lloyd-Hotel. Das historische Gebäude wurde aufwendig saniert und präsentiert sich heute als modernes, repräsentatives Büro- und Geschäftshaus.insert into rental_units (id, property_id, label, area_sqm, rent_per_sqm, rent_total_monthly, source, external_id) values (md5('unit-24103-1')::uuid, md5('property-24103')::uuid, 'Mietfläche', 1266, 25.1, null, 'filemaker', '24103-1') on conflict (id) do nothing;
