insert into properties (id, building_id, reference_number, slug, title, teaser, description, category, categories, property_type, status, price_type, price_note, commission_free, commission_months, commission_note, features, area_range_min_sqm, area_range_max_sqm, expose_pdf_url, featured_rank, source, external_id) values (md5('property-25281')::uuid, md5('building-grindelberg-7-20144')::uuid, '25281', 'hanseatisches-buerogebaeude-in-attraktiver-lage-mit-terrasse-25281', 'Hanseatisches Bürogebäude in attraktiver Lage mit Terrasse', 'In zentraler und zugleich äußerst attraktiver Lage zwischen Harvestehude, Hoheluft und dem Grindelviertel befindet sich diese exklusive Bürofläche am Grindelberg. Das Umfeld zählt …', 'In zentraler und zugleich äußerst attraktiver Lage zwischen Harvestehude, Hoheluft und dem Grindelviertel befindet sich diese exklusive Bürofläche am Grindelberg. Das Umfeld zählt zu den gefragtesten Büro- und Wohnlagen Hamburgs und überzeugt durch seine lebendige, urbane Atmosphäre sowie eine hervorragende Infrastruktur. Zahlreiche Cafés, Restaurants, Bars und vielfältige Einkaufsmöglichkeiten befinden sich in unmittelbarer Umgebung und schaffen ein angenehmes Arbeitsumfeld.insert into rental_units (id, property_id, label, area_sqm, rent_per_sqm, rent_total_monthly, source, external_id) values (md5('unit-25281-1')::uuid, md5('property-25281')::uuid, 'Mietfläche', 1268, 16, null, 'filemaker', '25281-1') on conflict (id) do nothing;
