insert into properties (id, building_id, reference_number, slug, title, teaser, description, category, categories, property_type, status, price_type, price_note, commission_free, commission_months, commission_note, features, area_range_min_sqm, area_range_max_sqm, expose_pdf_url, featured_rank, source, external_id) values (md5('property-25446')::uuid, md5('building-anckelmannsplatz-1-20537')::uuid, '25446', 'architektonisches-highlight-in-der-city-sued-25446', 'Architektonisches Highlight in der City Süd', 'Das futuristische Bürohaus wurde auf einer Länge von ca. 140 Metern über das Ende eines Hochwasserbassins errichtet. Unter dem Glasdach verbergen sich vier miteinander verbundene …', 'Das futuristische Bürohaus wurde auf einer Länge von ca. 140 Metern über das Ende eines Hochwasserbassins errichtet. Unter dem Glasdach verbergen sich vier miteinander verbundene Gebäudeteile, die durch sechs Wintergärten aufgelockert werden. Eine gute Anbindung an den ÖPNV ist durch die nahe gelegene U- und S-Bahnstation Berliner Tor gewährleistet. Die helle Fläche verfügt u.a. über Bodentanks mit Cat-6-Verkabelung, Beleuchtungssystem, außenliegenden elektrischen Sonnenschutz, eine aktive Be- und Entlüftung, eine Bauteilkühlung, teilweise Glastrennwänden, eine Pantry sowie separate WC-Einheiten. Diese Fläche ist bereits hochwertig ausgebaut. PKW-Stellplätze können nach Rücksprache angemietet werden. Diese Innenbilder sind beispielhaft gewählt und stammen aus einer ähnlichen Fläche im Objekt.', 'buero-praxis', array['buero-praxis']::property_category[], 'buero', 'published', 'qm', 'zzgl. NK u. MwSt.', true, null, 'Dieses Mietangebot ist courtagefrei für den Mieter bei Abschluss eines Mietvertrages mit einer festen Mietlaufzeit von mindestens 5 Jahren.', array['stellplaetze']::text[], 324, 4186, 'https://www.buerohamburg.de/objects/pdf/BHI_25446.pdf', null, 'filemaker', '25446') on conflict (id) do nothing;
