insert into properties (id, building_id, reference_number, slug, title, teaser, description, category, categories, property_type, status, price_type, price_note, commission_free, commission_months, commission_note, features, area_range_min_sqm, area_range_max_sqm, expose_pdf_url, featured_rank, source, external_id) values (md5('property-23477')::uuid, md5('building-suederstrasse-73-20097')::uuid, '23477', 'individuelle-bueroflaeche-mit-balkon-in-zentraler-citysued-lage-23477', 'Individuelle Bürofläche mit Balkon in zentraler CitySüd-Lage', 'Das aus vier Gebäudeabschnitten bestehende Büro-Center-City-Süd befindet sich zwischen den Elbbrücken und der Hamburger City nur wenige Meter von der S-Bahnstation Hammerbrook …', 'Das aus vier Gebäudeabschnitten bestehende Büro-Center-City-Süd befindet sich zwischen den Elbbrücken und der Hamburger City nur wenige Meter von der S-Bahnstation Hammerbrook entfernt. Zahlreiche gastronomische Einrichtungen sowie der schöne Mittelkanal sorgen für eine abwechselungsreiche und erholsame Mittagspause. Die Büroflächen können in Absprache mit dem zukünftigen Mieter aufgeteilt und ausgestattet werden. Die Grundausstattung umfasst u.a. hochwertigen Teppichboden in den Büroräumen, Amtico im Empfangsbereich, EDV-gerechte Beleuchtung, getrennte WC-Einheiten sowie eine Pantry. Das BCCS verfügt zudem über eine hauseigene Kantine. Die Innenansichten sind beispielhaft ausgewählt. PKW-Stellplätze können zusätzlich angemietet werden.', 'buero-praxis', array['buero-praxis']::property_category[], 'buero', 'published', 'qm', 'zzgl. NK u. MwSt.', true, null, 'Dieses Mietangebot ist courtagefrei für den Mieter bei Abschluss eines Mietvertrages mit einer festen Mietlaufzeit von mindestens 5 Jahren.', array['balkon-terrasse', 'stellplaetze']::text[], 377, 2756, 'https://www.buerohamburg.de/objects/pdf/BHI_23477.pdf', null, 'filemaker', '23477') on conflict (id) do nothing;
