insert into properties (id, building_id, reference_number, slug, title, teaser, description, category, categories, property_type, status, price_type, price_note, commission_free, commission_months, commission_note, features, area_range_min_sqm, area_range_max_sqm, expose_pdf_url, featured_rank, source, external_id) values (md5('property-16924')::uuid, md5('building-ludwig-erhard-strasse-22-20459')::uuid, '16924', 'traumhafter-rundumblick-ueber-hamburg-16924', 'Traumhafter Rundumblick über Hamburg', 'Der moderne und architektonisch ansprechende Bürokomplex befindet sich in guter Citylage zwischen Planten un Blomen und dem Rathausmarkt gegenüber der Michaeliskirche. Nach …', 'Der moderne und architektonisch ansprechende Bürokomplex befindet sich in guter Citylage zwischen Planten un Blomen und dem Rathausmarkt gegenüber der Michaeliskirche. Nach wenigen Metern erreicht man den Großneumarkt mit Zugang zu zahlreichen Cafés, Restaurants sowie allen Geschäften des täglichen Bedarfs. Die U- und S-Bahnstationen Stadthausbrücke und Rödingsmarkt liegen nur eine kurzen Fußweg entfernt und sorgen für eine gute Anbindung. Zusätzlich befindet sich direkt am Objekt die Bushaltestelle Michaeliskirche mit Anschluss an diverse Buslinien.insert into rental_units (id, property_id, label, area_sqm, rent_per_sqm, rent_total_monthly, source, external_id) values (md5('unit-16924-1')::uuid, md5('property-16924')::uuid, 'Mietfläche', 1312, 26, null, 'filemaker', '16924-1') on conflict (id) do nothing;
