insert into properties (id, building_id, reference_number, slug, title, teaser, description, category, categories, property_type, status, price_type, price_note, commission_free, commission_months, commission_note, features, area_range_min_sqm, area_range_max_sqm, expose_pdf_url, featured_rank, source, external_id) values (md5('property-23100')::uuid, md5('building-beim-strohhause-17-31-20097')::uuid, '23100', 'berliner-tor-center-helle-bueroflaeche-mit-weitblick-23100', 'Berliner Tor Center - Helle Bürofläche mit Weitblick', 'In äußerst verkehrsgünstiger Lage der Hamburger City zwischen der Elbe und der Außenalster befindet sich das markante und weit sichtbare Berliner Tor Center. Das 22-geschossige …', 'In äußerst verkehrsgünstiger Lage der Hamburger City zwischen der Elbe und der Außenalster befindet sich das markante und weit sichtbare Berliner Tor Center. Das 22-geschossige Büro-  und Geschäftsgebäude verfügt über ein repräsentatives, gläsernes Foyer sowie sechs Personenaufzüge. Zur Ausstattung der Fläche zählt ein Hohlraumboden, ein in die bodentiefen Fensterelemente integrierter Sonnenschutz sowie Kühldecken. Die Fläche kann den Wünschen des Mieters entsprechend aufgeteilt und ausgebaut werden. Tiefgaragenstellplätze können bei Bedarf angemietet werden. Diese Innenbilder sind beispielhaft gewählt.', 'buero-praxis', array['buero-praxis']::property_category[], 'buero', 'published', 'qm', 'zzgl. NK u. MwSt.', true, null, 'Dieses Mietangebot ist courtagefrei für den Mieter bei Abschluss eines Mietvertrages mit einer festen Mietlaufzeit von mindestens 5 Jahren.', array['barrierefrei', 'stellplaetze']::text[], 712, 2564, 'https://www.buerohamburg.de/objects/pdf/BHI_23100.pdf', null, 'filemaker', '23100') on conflict (id) do nothing;
