insert into properties (id, building_id, reference_number, slug, title, teaser, description, category, categories, property_type, status, price_type, price_note, commission_free, commission_months, commission_note, features, area_range_min_sqm, area_range_max_sqm, expose_pdf_url, featured_rank, source, external_id) values (md5('property-24068')::uuid, md5('building-christoph-probst-weg-26-31-20251')::uuid, '24068', 'top-bueroloft-im-historischen-zeughaus-mit-grossen-terrassen-24068', 'Top Büroloft im historischen Zeughaus mit großen Terrassen', 'Das im Rahmen einer umfassenden Sanierung komplett neu konzipierte und modernisierte ehemalige Zeughaus befindet sich in verkehrsgünstiger Lage zwischen der Hamburger City und dem …', 'Das im Rahmen einer umfassenden Sanierung komplett neu konzipierte und modernisierte ehemalige Zeughaus befindet sich in verkehrsgünstiger Lage zwischen der Hamburger City und dem Flughafen im westlichen Eppendorf. Eine gute Anbindung an die Autobahnen ist gegeben und der Anschluss an den ÖPNV durch Buslinien gesichert. Diverse gastronomische Einrichtungen sind im direkten Umfeld fußläufig schnell erreicht. Die lichtdurchflutete und loftartige Bürofläche ist hochwertig ausgebaut und u.a. mit einem Hohlraum- bzw. Doppelboden, zum Teil Sichtmauerwerk, einem außenliegenden Sonnenschutz sowie hochwertiger Bodenbelag. Die Aufteilung kann in Absprache den individuellen Bedürfnissen des neuen Mieters angepasst werden. Pkw-Stellplätze stehen zur Anmietung bereit. Highlight sind große Terrassenflächen mit ca. 266 qm welche zur o.g. Mietfläche dazu addiert wird. Diese Innenbilder sind beispielhaft gewählt.', 'buero-praxis', array['buero-praxis']::property_category[], 'buero', 'published', 'qm', 'zzgl. NK u. MwSt.', true, null, 'Dieses Mietangebot ist courtagefrei für den Mieter bei Abschluss eines Mietvertrages mit einer festen Mietlaufzeit von mindestens 5 Jahren.', array['erdgeschoss', 'stellplaetze']::text[], 958, 1528, 'https://www.buerohamburg.de/objects/pdf/BHI_24068.pdf', null, 'filemaker', '24068') on conflict (id) do nothing;
